:[{"x":2,"y":1}],"friends":[]},"robot_start":{"x":0,"y":1,"dir":"E"},"objectives":[{"type":"ACTIVATE_GENERATORS"},{"type":"REACH_GOAL"}],"rules":{"allowed_commands":["MOVE_FORWARD","ACTIVATE","TURN_LEFT","TURN_RIGHT"],"max_blocks":6}},"hints":[{"id":"00000008-0000-4000-8000-00000000003c","position":1,"text":{"en":"Stand on the generator, then use Activate.","th":"ยืนบนเครื่องกำเนิดพลังงานแล้วใช้คำสั่งเปิดใช้งาน"}},{"id":"00000008-0000-4000-8000-00000000003d","position":2,"text":{"en":"Move 2, Activate, then Move 4.","th":"เดิน 2 เปิดใช้งาน แล้วเดิน 4"}}]},{"id":"00000002-0000-4000-8000-000000000007","code":"level_07","world_id":"00000001-0000-4000-8000-000000000003","position":7,"version":1,"difficulty":3,"max_score":200,"time_limit_seconds":null,"scene_id":"00000003-0000-4000-8000-000000000003","robot_id":null,"completion_animation":"celebrate","unlock":{"type":"PREVIOUS_LEVEL"},"title":{"th":"เขาวงกตอวกาศ","en":"Space Maze"},"description":{"th":"ผสมคำสั่งเดิน เลี้ยว และกระโดด เพื่อผ่านเขาวงกตสถานีอวกาศ","en":"Combine walking, turning and jumping to cross the space station maze."},"mission":{"map":{"width":7,"height":5,"rows":["_____G_","_____._","___.H._","___.___","....___"],"crystals":[],"generators":[],"friends":[]},"robot_start":{"x":0,"y":4,"dir":"E"},"objectives":[{"type":"REACH_GOAL"}],"rules":{"allowed_commands":["MOVE_FORWARD","TURN_LEFT","TURN_RIGHT","JUMP"],"max_blocks":12}},"hints":[{"id":"00000008-0000-4000-8000-000000000046","position":1,"text":{"en":"Follow the path: east, north, east (jump!), then north.","th":"ตามทางไป: ตะวันออก เหนือ ตะวันออก (กระโดด!) แล้วเหนือ"}},{"id":"00000008-0000-4000-8000-000000000047","position":2,"text":{"en":"Move 3, Left, Move 2, Right, Jump, Left, Move 2.","th":"เดิน 3 ซ้าย เดิน 2 ขวา กระโดด ซ้าย เดิน 2"}}]},{"id":"00000002-0000-4000-8000-000000000008","code":"level_08","world_id":"00000001-0000-4000-8000-000000000003","position":8,"version":1,"difficulty":3,"max_score":200,"time_limit_seconds":null,"scene_id":"00000003-0000-4000-8000-000000000003","robot_id":null,"completion_animation":"celebrate","unlock":{"type":"PREVIOUS_LEVEL"},"title":{"th":"ภารกิจช่วยเพื่อน","en":"Rescue Mission"},"description":{"th":"หุ่นยนต์เพื่อนติดอยู่บนสถานี ข้ามหลุมไปแล้วช่วยมันออกมา!","en":"A friendly robot is stuck on the station. Cross the gap and rescue it!"},"mission":{"map":{"width":7,"height":4,"rows":["_____._","_____._","_____._","...O..."],"crystals":[],"generators":[],"friends":[{"x":5,"y":0}]},"robot_start":{"x":0,"y":3,"dir":"E"},"objectives":[{"type":"RESCUE_FRIENDS"}],"rules":{"allowed_commands":["MOVE_FORWARD","TURN_LEFT","TURN_RIGHT","JUMP","PICK_UP"],"max_blocks":12}},"hints":[{"id":"00000008-0000-4000-8000-000000000050","position":1,"text":{"en":"Never walk into the gap — jump over it!","th":"อย่าเดินลงหลุม — กระโดดข้ามไป!"}},{"id":"00000008-0000-4000-8000-000000000051","position":2,"text":{"en":"Move 2, Jump, Move 1, Turn Left, Move 3, Pick Up.","th":"เดิน 2 กระโดด เดิน 1 เลี้ยวซ้าย เดิน 3 เก็บ"}}]},{"id":"00000002-0000-4000-8000-000000000009","code":"level_09","world_id":"00000001-0000-4000-8000-000000000003","position":9,"version":1,"difficulty":4,"max_score":200,"time_limit_seconds":null,"scene_id":"00000003-0000-4000-8000-000000000003","robot_id":null,"completion_animation":"celebrate","unlock":{"type":"PREVIOUS_LEVEL"},"title":{"th":"บันไดแห่งการวนซ้ำ","en":"Staircase Loop"},"description":{"th":"ปีนบันไดไปยังเป้าหมาย ใช้บล็อกทำซ้ำ — ถ้าไม่ใช้บล็อกจะไม่พอ!","en":"Climb the staircase to the goal. Use the Repeat block — you do not have enough blocks without it!"},"mission":{"map":{"width":6,"height":6,"rows":["_____G","____..","___.._","__..__","_..___","..____"],"crystals":[],"generators":[],"friends":[]},"robot_start":{"x":0,"y":5,"dir":"E"},"objectives":[{"type":"REACH_GOAL"}],"rules":{"allowed_commands":["MOVE_FORWARD","TURN_LEFT","TURN_RIGHT","REPEAT"],"max_blocks":8,"required_commands":["REPEAT"]}},"hints":[{"id":"00000008-0000-4000-8000-00000000005a","position":1,"text":{"en":"Each step is the same: forward, left, forward, right.","th":"ทุกขั้นเหมือนกัน: เดินหน้า เลี้ยวซ้าย เดินหน้า เลี้ยวขวา"}},{"id":"00000008-0000-4000-8000-00000000005b","position":2,"text":{"en":"Put those 4 blocks inside a Repeat that runs 5 times.","th":"ใส่ 4 บล็อกนั้นไว้ในบล็อกทำซ้ำ 5 ครั้ง"}}]},{"id":"00000002-0000-4000-8000-00000000000a","code":"level_10","world_id":"00000001-0000-4000-8000-000000000004","position":10,"version":1,"difficulty":5,"max_score":200,"time_limit_seconds":null,"scene_id":"00000003-0000-4000-8000-000000000004","robot_id":null,"completion_animation":"celebrate","unlock":{"type":"PREVIOUS_LEVEL"},"title":{"th":"ภารกิจสุดท้าย","en":"The Final Mission"},"description":{"th":"เก็บคริสตัลทั้ง 2 ก้อน เปิดเครื่องกำเนิดพลังงาน ช่วยเพื่อน ไปที่เป้าหมาย แล้วฉลอง!","en":"Collect both crystals, power up the generator, rescue your friend, reach the goal and celebrate!"},"mission":{"map":{"width":7,"height":5,"rows":["______G","______.","______.","______D","....O.."],"crystals":[{"x":2,"y":4},{"x":6,"y":2}],"generators":[{"x":6,"y":4}],"friends":[{"x":6,"y":1}]},"robot_start":{"x":0,"y":4,"dir":"E"},"objectives":[{"type":"COLLECT_CRYSTALS"},{"type":"ACTIVATE_GENERATORS"},{"type":"RESCUE_FRIENDS"},{"type":"REACH_GOAL"},{"type":"CELEBRATE"}],"rules":{"allowed_commands":["MOVE_FORWARD","MOVE_BACKWARD","TURN_LEFT","TURN_RIGHT","JUMP","WAVE","PICK_UP","ACTIVATE","CELEBRATE","REPEAT","WAIT"],"max_blocks":20}},"hints":[{"id":"00000008-0000-4000-8000-000000000064","position":1,"text":{"en":"Make a plan: crystal, jump the gap, generator, door, crystal, friend, goal.","th":"วางแผน: คริสตัล กระโดดข้ามหลุม เครื่องกำเนิด ประตู คริสตัล เพื่อน เป้าหมาย"}},{"id":"00000008-0000-4000-8000-000000000065","position":2,"text":{"en":"The door opens only after you Activate the generator.","th":"ประตูจะเปิดเมื่อคุณเปิดใช้งานเครื่องกำเนิดพลังงานแล้วเท่านั้น"}},{"id":"00000008-0000-4000-8000-000000000066","position":3,"text":{"en":"Finish with Celebrate while standing on the goal.","th":"จบด้วยการฉลองขณะยืนอยู่บนเป้าหมาย"}}]}],"blocks":[{"command_type":"MOVE_FORWARD","category":"movement","label":{"th":"เดินหน้า","en":"Move Forward"},"description":{"th":"เดินไปข้างหน้าตามจำนวนก้าว","en":"Walk forward the given number of steps."},"color":"#3b82f6","icon":"arrow-up","params":[{"name":"steps","min":1,"max":10,"default":1}],"enabled":true,"position":1},{"command_type":"MOVE_BACKWARD","category":"movement","label":{"th":"ถอยหลัง","en":"Move Backward"},"description":{"th":"ถอยหลังตามจำนวนก้าว โดยไม่หมุนตัว","en":"Step backward without turning around."},"color":"#6366f1","icon":"arrow-down","params":[{"name":"steps","min":1,"max":10,"default":1}],"enabled":true,"position":2},{"command_type":"TURN_LEFT","category":"movement","label":{"th":"เลี้ยวซ้าย","en":"Turn Left"},"description":{"th":"หมุนตัวไปทางซ้าย 90 องศา","en":"Rotate 90 degrees to the left."},"color":"#0ea5e9","icon":"corner-up-left","params":[],"enabled":true,"position":3},{"command_type":"TURN_RIGHT","category":"movement","label":{"th":"เลี้ยวขวา","en":"Turn Right"},"description":{"th":"หมุนตัวไปทางขวา 90 องศา","en":"Rotate 90 degrees to the right."},"color":"#0891b2","icon":"corner-up-right","params":[],"enabled":true,"position":4},{"command_type":"JUMP","category":"actions","label":{"th":"กระโดด","en":"Jump"},"description":{"th":"กระโดดข้ามช่องข้างหน้า 1 ช่อง","en":"Leap over the cell in front of you."},"color":"#f97316","icon":"chevrons-up","params":[],"enabled":true,"position":5},{"command_type":"WAVE","category":"actions","label":{"th":"โบกมือ","en":"Wave"},"description":{"th":"โบกมือทักทาย","en":"Wave hello."},"color":"#ec4899","icon":"hand","params":[],"enabled":true,"position":6},{"command_type":"PICK_UP","category":"actions","label":{"th":"เก็บ/ช่วย","en":"Pick Up / Rescue"},"description":{"th":"เก็บคริสตัลหรือช่วยหุ่นยนต์ในช่องที่ยืนอยู่","en":"Collect a crystal or rescue a robot on your cell."},"color":"#eab308","icon":"gem","params":[],"enabled":true,"position":7},{"command_type":"ACTIVATE","category":"actions","label":{"th":"เปิดใช้งาน","en":"Activate"},"description":{"th":"เปิดเครื่องกำเนิดพลังงานในช่องที่ยืนอยู่","en":"Switch on the generator on your cell."},"color":"#22c55e","icon":"zap","params":[],"enabled":true,"position":8},{"command_type":"CELEBRATE","category":"actions","label":{"th":"ฉลอง","en":"Celebrate"},"description":{"th":"ฉลองความสำเร็จ!","en":"Celebrate your success!"},"color":"#a855f7","icon":"party-popper","params":[],"enabled":true,"position":9},{"command_type":"REPEAT","category":"logic","label":{"th":"ทำซ้ำ","en":"Repeat"},"description":{"th":"ทำคำสั่งข้างในซ้ำตามจำนวนครั้ง","en":"Run the commands inside several times."},"color":"#14b8a6","icon":"repeat","params":[{"name":"times","min":2,"max":20,"default":2}],"enabled":true,"position":10},{"command_type":"WAIT","category":"logic","label":{"th":"รอ","en":"Wait"},"description":{"th":"หยุดรอตามจำนวนวินาที","en":"Pause for the given number of seconds."},"color":"#94a3b8","icon":"timer","params":[{"name":"seconds","min":1,"max":5,"default":1}],"enabled":true,"position":11}],"lessons":[{"id":"00000005-0000-4000-8000-000000000001","position":1,"image_url":null,"video_url":null,"demo_program":null,"title":{"th":"การเขียนโปรแกรมคืออะไร?","en":"What is Programming?"},"summary":{"th":"การสั่งงานคอมพิวเตอร์อย่างชัดเจน","en":"Giving clear instructions to a computer."},"body":{"th":"## การเขียนโปรแกรม = การสั่งงานอย่างชัดเจน\nการเขียนโปรแกรมคือการบอกคอมพิวเตอร์ว่าต้องทำ **อะไร** ทีละขั้นตอน\n\n- คอมพิวเตอร์เดาใจเราไม่ได้\n- มันทำตามที่เราสั่งเท่านั้น\n- รายการคำสั่งเรียกว่า **โปรแกรม**\n\nวันนี้ *คุณ* คือโปรแกรมเมอร์ และหุ่นยนต์จะทำตามโปรแกรมของคุณ!","en":"## Programming = clear instructions\nProgramming means telling a computer **exactly** what to do, one step at a time.\n\n- A computer cannot guess what you want.\n- It does only what you tell it.\n- A list of instructions is called a **program**.\n\nToday *you* are the programmer, and the robot will follow your program!"}},{"id":"00000005-0000-4000-8000-000000000002","position":2,"image_url":null,"video_url":null,"demo_program":[{"type":"MOVE_FORWARD","steps":2},{"type":"WAVE"}],"title":{"th":"ทำความรู้จักคำสั่ง","en":"Understanding Commands"},"summary":{"th":"บล็อกแต่ละอันคือคำสั่งหนึ่งคำสั่ง","en":"Each block is one command."},"body":{"th":"## บล็อกคือคำสั่ง\nในเกมนี้ **บล็อก** สีสันสดใสแต่ละอันคือคำสั่งสำหรับหุ่นยนต์\n\n- **เดินหน้า** ทำให้หุ่นยนต์เดิน\n- **โบกมือ** ทำให้หุ่นยนต์ทักทาย\n- บางบล็อกมีตัวเลข เช่น *จำนวนก้าว*\n\nลากบล็อกมาต่อกันในพื้นที่ทำงาน แล้วกด **COMPILE** เพื่อรันโปรแกรม","en":"## Blocks are commands\nIn this game every colorful **block** is a command for the robot.\n\n- **Move Forward** makes the robot walk.\n- **Wave** makes it say hello.\n- Some blocks have a number, like *how many steps*.\n\nDrag blocks into the workspace and snap them together. Then press **COMPILE** to run your program."}},{"id":"00000005-0000-4000-8000-000000000003","position":3,"image_url":null,"video_url":null,"demo_program":[{"type":"MOVE_FORWARD","steps":1},{"type":"TURN_LEFT"},{"type":"MOVE_FORWARD","steps":1}],"title":{"th":"ลำดับและการเรียงคำสั่ง","en":"Sequence and Order"},"summary":{"th":"คำสั่งทำงานจากบนลงล่าง","en":"Commands run from top to bottom."},"body":{"th":"## ลำดับสำคัญมาก!\nหุ่นยนต์ทำตามบล็อกของคุณ **จากบนลงล่าง**\n\n- เดิน 1 แล้วเลี้ยวซ้าย: หุ่นยนต์เดินแล้วจึงเลี้ยว\n- เลี้ยวซ้ายแล้วเดิน 1: หุ่นยนต์เลี้ยวแล้วเดินไปอีกทางหนึ่ง!\n\nเปลี่ยนลำดับ ผลลัพธ์ก็เปลี่ยน ถ้าหุ่นยนต์เดินผิดทาง ให้ตรวจลำดับคำสั่ง","en":"## Order matters!\nThe robot runs your blocks **from top to bottom**.\n\n- Move 1, then turn left: the robot walks, then turns.\n- Turn left, then move 1: the robot turns, then walks somewhere else!\n\nChanging the order changes the result. If your robot goes the wrong way, check the order."}},{"id":"00000005-0000-4000-8000-000000000004","position":4,"image_url":null,"video_url":null,"demo_program":[{"type":"MOVE_FORWARD","steps":2},{"type":"JUMP"},{"type":"MOVE_BACKWARD","steps":1}],"title":{"th":"คำสั่งการเคลื่อนที่","en":"Movement Commands"},"summary":{"th":"เดินหน้า ถอยหลัง และกระโดด","en":"Forward, backward and jump."},"body":{"th":"## การเคลื่อนที่ของหุ่นยนต์\n- **เดินหน้า** *(1–10 ก้าว)* เดินไปตามทิศที่หุ่นยนต์หันหน้าอยู่\n- **ถอยหลัง** ก้าวถอยโดยไม่หมุนตัว\n- **กระโดด** ข้ามช่องข้างหน้า ทั้งสิ่งกีดขวางและหลุม!\n\nระวัง: ถ้าเดินชนกำแพง สิ่งกีดขวาง หรือตกหลุม ภารกิจจะล้มเหลว ใช้ **กระโดด** เพื่อข้ามสิ่งกีดขวางและหลุม","en":"## Moving the robot\n- **Move Forward** *(1–10 steps)* walks in the direction the robot faces.\n- **Move Backward** steps back without turning around.\n- **Jump** leaps over the square in front: over a barrier or a gap!\n\nCareful: walking into a wall, a barrier, or a gap means the mission fails. Use **Jump** to cross barriers and gaps."}},{"id":"00000005-0000-4000-8000-000000000005","position":5,"image_url":null,"video_url":null,"demo_program":[{"type":"TURN_LEFT"},{"type":"MOVE_FORWARD","steps":1},{"type":"TURN_RIGHT"}],"title":{"th":"การเลี้ยวและทิศทาง","en":"Turns and Directions"},"summary":{"th":"เลี้ยวซ้ายหรือขวา 90 องศา","en":"Turn left or right by 90 degrees."},"body":{"th":"## การเลี้ยว\n- **เลี้ยวซ้าย** หมุนหุ่นยนต์ไปทางซ้าย 90°\n- **เลี้ยวขวา** หมุนหุ่นยนต์ไปทางขวา 90°\n\nซ้ายและขวานับจากมุมมองของ **หุ่นยนต์** ไม่ใช่ของเรา\n\nเคล็ดลับ: การเลี้ยวไม่ทำให้หุ่นยนต์เคลื่อนที่ ต้องเดินต่อหลังเลี้ยว!","en":"## Turning\n- **Turn Left** rotates the robot 90° to its left.\n- **Turn Right** rotates the robot 90° to its right.\n\nLeft and right are always from the **robot''s** point of view, not yours.\n\nTip: Turning does not move the robot. Walk after you turn!"}},{"id":"00000005-0000-4000-8000-000000000006","position":6,"image_url":null,"video_url":null,"demo_program":[{"type":"REPEAT","times":3,"body":[{"type":"MOVE_FORWARD","steps":1},{"type":"WAVE"}]}],"title":{"th":"การทำคำสั่งซ้ำ","en":"Repeating Commands"},"summary":{"th":"ลูปช่วยประหยัดเวลาและบล็อก","en":"Loops save time and blocks."},"body":{"th":"## ลูป\nบางครั้งเราต้องใช้คำสั่งเดิมซ้ำ ๆ\n\nแทนที่จะใช้บล็อกเหมือนกัน 10 อัน ให้ใช้บล็อก **ทำซ้ำ** อันเดียวแล้ววางคำสั่งไว้ข้างใน ตั้งจำนวนครั้งที่ต้องการทำซ้ำ\n\n- โปรแกรมสั้นลง\n- ผิดพลาดน้อยลง\n- โปรแกรมเมอร์ชอบลูป!","en":"## Loops\nSometimes you need the same commands again and again.\n\nInstead of 10 identical blocks, use one **Repeat** block and put the commands inside it. Set how many times to repeat.\n\n- Shorter programs\n- Fewer mistakes\n- Programmers love loops!"}},{"id":"00000005-0000-4000-8000-000000000007","position":7,"image_url":null,"video_url":null,"demo_program":[{"type":"MOVE_FORWARD","steps":2},{"type":"PICK_UP"},{"type":"TURN_LEFT"},{"type":"MOVE_FORWARD","steps":1}],"title":{"th":"การแก้ปัญหา","en":"Solving Problems"},"summary":{"th":"วางแผน ทดลอง แก้ไข แล้วลองใหม่","en":"Plan, test, fix, try again."},"body":{"th":"## เป็นนักแก้ปัญหา\n1. **ดู** แผนที่และหาเป้าหมาย\n2. **วางแผน** เส้นทางเป็นขั้นตอนเล็ก ๆ\n3. **สร้าง** บล็อกของคุณ\n4. **ทดลอง** ด้วย COMPILE\n5. **แก้ไข** ข้อผิดพลาดแล้วลองใหม่ โปรแกรมเมอร์ทุกคนทำแบบนี้!\n\nติดขัดใช่ไหม? ใช้ **คำใบ้** ได้ เสียคะแนนเล็กน้อย แต่ช่วยให้ทำภารกิจสำเร็จ","en":"## Be a problem solver\n1. **Look** at the map and find the goal.\n2. **Plan** the path in small steps.\n3. **Build** your blocks.\n4. **Test** with COMPILE.\n5. **Fix** mistakes and try again. Every programmer does this!\n\nStuck? Use a **hint**. It costs a few points, but it can help you finish the mission."}}],"robots":[{"id":"00000004-0000-4000-8000-000000000001","name":{"en":"Bolt","th":"โบลต์"},"kind":"builtin","builtin_style":"bolt","sprite_url":null,"frame_width":null,"frame_height":null,"animations":{},"scale":1,"move_speed_ms":450,"primary_color":"#38bdf8","is_default":true},{"id":"00000004-0000-4000-8000-000000000002","name":{"en":"Nova","th":"โนวา"},"kind":"builtin","builtin_style":"nova","sprite_url":null,"frame_width":null,"frame_height":null,"animations":{},"scale":1,"move_speed_ms":450,"primary_color":"#f472b6","is_default":false},{"id":"00000004-0000-4000-8000-000000000003","name":{"en":"Gizmo","th":"กิซโม่"},"kind":"builtin","builtin_style":"gizmo","sprite_url":null,"frame_width":null,"frame_height":null,"animations":{},"scale":1,"move_speed_ms":450,"primary_color":"#4ade80","is_default":false}],"scenes":[{"id":"00000003-0000-4000-8000-000000000001","name":{"en":"Training Station","th":"สถานีฝึก"},"kind":"builtin","theme":"training","image_url":null,"width":960,"height":540,"parallax":[]},{"id":"00000003-0000-4000-8000-000000000002","name":{"en":"Energy Planet","th":"ดาวพลังงาน"},"kind":"builtin","theme":"energy","image_url":null,"width":960,"height":540,"parallax":[]},{"id":"00000003-0000-4000-8000-000000000003","name":{"en":"Lost Station","th":"สถานีที่สาบสูญ"},"kind":"builtin","theme":"station","image_url":null,"width":960,"height":540,"parallax":[]},{"id":"00000003-0000-4000-8000-000000000004","name":{"en":"Final Mission","th":"ภารกิจสุดท้าย"},"kind":"builtin","theme":"final","image_url":null,"width":960,"height":540,"parallax":[]}]}'::jsonb, 'Initial seed configuration');
